"use client"

import React from "react"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"

import { zodResolver } from "@hookform/resolvers/zod"
import { useForm } from "react-hook-form"
import { toast } from "sonner"
import { z } from "zod"
import { Button } from "@/components/ui/button"
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormMessage,
} from "@/components/ui/form"
import { Textarea } from "@/components/ui/textarea" 
import DiscreteSliderSteps from "../components/Slider"

//font
import {DM_Sans} from "next/font/google";

const DMsansFont = DM_Sans({
  weight: "400",
  subsets: ["latin"],
})


const FormSchema = z.object({
  entry: z.string().min(5, {
    message: "Your journal entry must be at least 5 characters.",
  }),
})

const MoodJournal = () => {
  const form = useForm<z.infer<typeof FormSchema>>({
    resolver: zodResolver(FormSchema),
    defaultValues: {
      entry: "",
    },
  })

  function onSubmit(data: z.infer<typeof FormSchema>) {
    toast("Journal Entry Submitted", {
      description: (
        <pre className="mt-2 w-[320px] rounded-md bg-neutral-950 p-4">
          <code className="text-white whitespace-pre-wrap">
            {data.entry}
          </code>
        </pre>
      ),
    })
  }

  return (
    <div className="flex flex-col min-h-screen">
      <div className="navbar bg-base-100">
        <div className="navbar-start"></div>
        <h1 className="navbar-center text-5xl">Mood Journal</h1>
        <div className="navbar-end"></div>
      </div>
      
      <div className="moodSliderComponent flex flex-row gap-4 p-4">
        <div className="mood-card">
          <Card>
            <CardHeader>
              <CardTitle>How&apos;s your mood?</CardTitle>
            </CardHeader>
            <CardContent>
              <DiscreteSliderSteps/>
            </CardContent>
          </Card>
        </div>

        <div className="energy-card">
          <Card>
            <CardHeader>
              <CardTitle>How energetic do you feel?</CardTitle>
            </CardHeader>
            <CardContent>
              <DiscreteSliderSteps/>
            </CardContent>
          </Card>
        </div>

        <div className="stress-card">
          <Card>
            <CardHeader>
              <CardTitle>How stressed do you feel?</CardTitle>
            </CardHeader>
            <CardContent>
              <DiscreteSliderSteps/>
            </CardContent>
          </Card>
        </div>
      </div>


      <div className="journal-section p-4">
        <Card>
          <CardHeader>
            <CardTitle>Today&apos;s Prompt:</CardTitle>
            <CardDescription>
              What&apos;s one thing you would have done differently today?
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form
                onSubmit={form.handleSubmit(onSubmit)}
                className="w-full max-w-xl space-y-6"
              >
                <FormField
                  control={form.control}
                  name="entry"
                  render={({ field }) => (
                    <FormItem>
                      <FormControl>
                        <Textarea
                          placeholder="Write your thoughts here..."
                          className="min-h-[120px] max-w"
                          {...field}
                        />
                      </FormControl>
                      <FormDescription>
                        Be honest with yourself — no one else will see this.
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <Button type="submit">Save Entry</Button>
              </form>
            </Form>
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

export default MoodJournal

